<?php $e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');$rate=static function($v){$v=(float)$v;foreach(['B/s','KB/s','MB/s','GB/s'] as $u){if($v<1024)return number_format($v,$v<10?1:0).' '.$u;$v/=1024;}return number_format($v,1).' TB/s';};?>
<div x-data="{q:''}" class="space-y-5"><header class="flex flex-wrap items-end justify-between gap-3"><div><h1 class="text-3xl font-bold">Manejar servidores</h1><p class="text-slate-400">Estado, capacidad y servicios de todo el clúster OrionX.</p></div><a href="/deployments" class="bg-emerald-700 hover:bg-emerald-600 px-4 py-2 rounded-lg font-medium">＋ Instalar balanceador</a></header>
<section class="bg-slate-900 border border-slate-800 rounded-xl overflow-hidden"><div class="p-4 flex justify-between gap-3"><span class="text-sm text-slate-400"><?=count($servers)?> servidores</span><input x-model="q" placeholder="Buscar servidor o IP…" class="bg-slate-800 border border-slate-700 rounded-lg px-3 py-2 w-72"></div><div class="overflow-x-auto"><table class="w-full text-sm min-w-[1280px]"><thead class="bg-slate-800/80 text-xs uppercase text-slate-400"><tr><th class="p-3">Orden</th><th>Estado</th><th class="text-left">Servidor</th><th class="text-left">IP / Región</th><th>Conexiones</th><th>Red</th><th>CPU</th><th>RAM</th><th>Disco</th><th>Servicios</th><th>Heartbeat</th><th>Versión</th><th class="p-3">Acciones</th></tr></thead><tbody class="divide-y divide-slate-800"><?php foreach($servers as $s):$stale=!$s['last_heartbeat_at']||strtotime($s['last_heartbeat_at'])<time()-90;$online=!$stale&&in_array($s['status'],['online','degraded'],true);$search=strtolower($s['name'].' '.$s['public_ip'].' '.$s['private_ip'].' '.$s['region']);?><tr x-show="!q||<?=htmlspecialchars(json_encode($search),ENT_QUOTES)?>.includes(q.toLowerCase())" class="hover:bg-slate-800/35"><td class="p-3 text-center"><?=$s['priority']?></td><td class="text-center"><i class="inline-block w-3 h-3 rounded-full <?=$online?($s['status']==='degraded'?'bg-amber-400':'bg-emerald-400'):'bg-red-500'?>" title="<?=$e($stale?'Sin heartbeat':$s['status'])?>"></i></td><td><strong><?=$e($s['name'])?></strong><div class="text-xs text-slate-500"><?=$e($s['tls_domain']?:'Sin dominio TLS')?></div></td><td><div><?=$e($s['public_ip']?:'—')?></div><div class="text-xs text-slate-500"><?=$e($s['region']?:'Sin región')?><?=$s['private_ip']?' · '.$e($s['private_ip']):''?></div></td><td class="text-center"><strong class="text-blue-300"><?=number_format((int)$s['active_sessions'])?></strong><div class="text-xs text-slate-500">de <?=number_format((int)$s['max_capacity'])?></div></td><td class="text-center"><div class="text-emerald-400">↑ <?=$rate($s['network_tx_bps'])?></div><div class="text-cyan-400">↓ <?=$rate($s['network_rx_bps'])?></div></td><?php foreach(['cpu','ram','disk'] as $m):$v=min(100,max(0,(float)$s[$m]));?><td><div class="mx-auto grid place-items-center w-12 h-12 rounded-full" style="background:conic-gradient(<?=$v>=90?'#ef4444':($v>=75?'#f59e0b':'#10b981')?> <?=$v?>%,#1e293b 0)"><span class="grid place-items-center w-9 h-9 rounded-full bg-slate-900 text-xs"><?=number_format($v)?>%</span></div></td><?php endforeach?><td class="text-center text-xs"><?php foreach(['nginx_status'=>'Nginx','ffmpeg_status'=>'FFmpeg','agent_status'=>'Agente'] as $key=>$label):?><div class="<?=$s[$key]==='ok'?'text-emerald-400':'text-red-400'?>"><?=$label?></div><?php endforeach?></td><td class="text-center text-xs <?=$stale?'text-red-400':'text-emerald-400'?>"><?=$s['last_heartbeat_at']?$e($s['last_heartbeat_at']):'Nunca'?></td><td class="text-center"><?=$e($s['installed_version']?:'Pendiente')?></td><td class="p-3"><div class="flex justify-center gap-1"><a title="Instalar o actualizar" href="/deployments" class="bg-blue-700 px-2 py-1.5 rounded">⚙</a><a title="Certificado TLS" href="/certificates" class="bg-slate-700 px-2 py-1.5 rounded">▣</a><?php foreach(['online'=>'▶','draining'=>'⇥'] as $mode=>$icon):?><form method="post" action="/servers/mode"><?=$csrf->field()?><input type="hidden" name="id" value="<?=$s['id']?>"><input type="hidden" name="mode" value="<?=$mode?>"><button title="<?=$mode==='online'?'Activar':'Drenar'?>" class="<?=$mode==='online'?'bg-emerald-700':'bg-amber-700'?> px-2 py-1.5 rounded"><?=$icon?></button></form><?php endforeach?></div></td></tr><?php endforeach?><?php if(!$servers):?><tr><td colspan="13" class="p-12 text-center text-slate-500">No hay servidores registrados.</td></tr><?php endif?></tbody></table></div></section></div>
